        {
            porId[c.ChunkId] = c;
        }

        var fusion = Rrf.Fusionar([a.Select(c => c.ChunkId).ToList(), b.Select(c => c.ChunkId).ToList()], k);
        return fusion.Take(topK).Select(id => RetrievalFilter.ToFragmento(porId[id])).ToList();
    }
}
