using System.Globalization;

namespace TutorFlow.Application.Retrieval;

/// <summary>Configuracion invalida de embeddings (vector/hybrid sin EMBEDDING_* completo). Falla al arrancar.</summary>
public sealed class EmbeddingConfiguracionException(string message) : InvalidOperationException(message);

/// <summary>Uso acumulado de embeddings (tokens de entrada y costo en USD).</summary>
public interface IEmbeddingUsageReporter
{
    long Tokens { get; }

    decimal CostoUsd { get; }
}

/// <summary>
/// Configuracion de embeddings (SPEC 11): EMBEDDING_PROVIDER (openai-compatible), EMBEDDING_MODEL, EMBEDDING_API_KEY,
/// EMBEDDING_PRICE_PER_MTOK y, opcionales, EMBEDDING_BASE_URL (si falta se usa LLM_BASE_URL solo cuando
/// LLM_PROVIDER es openai-compatible; si no, https://api.openai.com/v1) y EMBEDDING_CACHE_PATH (archivo de cache).
/// <see cref="ApiKey"/> jamas se imprime.
/// </summary>
public sealed record EmbeddingOptions
{
    public const string OpenAiCompatible = "openai-compatible";
    public const string DefaultBaseUrl = "https://api.openai.com/v1";

    public string? Provider { get; init; }

    public string? Model { get; init; }

    public string? ApiKey { get; init; }

    public string? BaseUrl { get; init; }

    public decimal PrecioPorMtok { get; init; }

    public string? CachePath { get; init; }

    public bool Configurado =>
        !string.IsNullOrWhiteSpace(Provider) && !string.IsNullOrWhiteSpace(Model) && !string.IsNullOrWhiteSpace(ApiKey);

    public override string ToString() => $"EmbeddingOptions(Provider={Provider}, Model={Model})";

    public static EmbeddingOptions FromConfig(Func<string, string?> get)
    {
        ArgumentNullException.ThrowIfNull(get);
        var baseUrl = Valor(get("EMBEDDING_BASE_URL"));
        if (baseUrl is null && string.Equals(Valor(get("LLM_PROVIDER")), "openai-compatible", StringComparison.OrdinalIgnoreCase))
        {
            baseUrl = Valor(get("LLM_BASE_URL"));
        }

        decimal precio = 0m;
        if (Valor(get("EMBEDDING_PRICE_PER_MTOK")) is { } p
            && (!decimal.TryParse(p, NumberStyles.Number, CultureInfo.InvariantCulture, out precio) || precio < 0))
        {
            throw new EmbeddingConfiguracionException("EMBEDDING_PRICE_PER_MTOK debe ser un decimal no negativo (punto decimal).");
        }

        return new EmbeddingOptions
        {
            Provider = Valor(get("EMBEDDING_PROVIDER"))?.ToLowerInvariant(),
            Model = Valor(get("EMBEDDING_MODEL")),
            ApiKey = Valor(get("EMBEDDING_API_KEY")),
            BaseUrl = baseUrl,
            PrecioPorMtok = precio,
            CachePath = Valor(get("EMBEDDING_CACHE_PATH")),
        };
    }

    /// <summary>Lanza si falta algo para usar vector/hybrid. El mensaje nombra variables, nunca valores.</summary>
    public void ExigirParaVectorial(string estrategia)
    {
        var faltan = new List<string>();
        if (string.IsNullOrWhiteSpace(Provider))
        {
            faltan.Add("EMBEDDING_PROVIDER");
        }
        else if (Provider != OpenAiCompatible)
        {
            throw new EmbeddingConfiguracionException(
                $"EMBEDDING_PROVIDER '{Provider}' no es valido. Valor admitido: {OpenAiCompatible}.");
        }

        if (string.IsNullOrWhiteSpace(Model))
        {
            faltan.Add("EMBEDDING_MODEL");
        }

        if (string.IsNullOrWhiteSpace(ApiKey))
        {
            faltan.Add("EMBEDDING_API_KEY");
        }

        if (faltan.Count > 0)
        {
            throw new EmbeddingConfiguracionException(
                $"RETRIEVAL_STRATEGY '{estrategia}' requiere embeddings configurados; faltan: {string.Join(", ", faltan)}.");
        }

        if (CachePath is not null && EstaBajoSrc(CachePath))
        {
            throw new EmbeddingConfiguracionException("EMBEDDING_CACHE_PATH no puede apuntar dentro de src/.");
        }
    }

    private static bool EstaBajoSrc(string path)
    {
        var partes = Path.GetFullPath(path).Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
        return partes.Contains("src", StringComparer.Ordinal);
    }

    private static string? Valor(string? v) => string.IsNullOrWhiteSpace(v) ? null : v.Trim();
}

using TutorFlow.Application.Ports;

namespace TutorFlow.Application.Retrieval;

/// <summary>Ranking completo de chunks elegibles para una pregunta (base de top-k y de RRF).</summary>
public interface IChunkRanker
{
    Task<IReadOnlyList<Chunk>> RankearAsync(string pregunta, CancellationToken ct);
}

/// <summary>Persistencia opcional de embeddings de chunks (clave = modelo + hash del chunk).</summary>
public interface IEmbeddingCache
{
    float[]? Obtener(string clave);

    void Guardar(string clave, float[] vector);

    void Persistir();
}

public static class Vectores
{
    public static double Coseno(float[] a, float[] b)
    {
        if (a.Length != b.Length)
        {
            throw new ArgumentException("Dimensiones de embedding distintas.");
        }

        double dot = 0, na = 0, nb = 0;
        for (var i = 0; i < a.Length; i++)
        {
            dot += (double)a[i] * b[i];
            na += (double)a[i] * a[i];
            nb += (double)b[i] * b[i];
        }

        return na == 0 || nb == 0 ? 0 : dot / (Math.Sqrt(na) * Math.Sqrt(nb));
    }
}

/// <summary>Embeddings de chunks confiables + coseno en memoria, top-k=4. Los untrusted jamas se envian al proveedor.</summary>
public sealed class VectorRetriever : IRetriever, IChunkRanker
{
    public const int DefaultTopK = 4;
    private const int Lote = 64;
    private readonly IChunkCatalog _catalog;
    private readonly IEmbeddingClient _embeddings;
    private readonly string _modelo;
    private readonly IEmbeddingCache? _cache;
    private readonly int _topK;
    private readonly SemaphoreSlim _init = new(1, 1);
    private Dictionary<string, float[]>? _vectores;

    public VectorRetriever(IChunkCatalog catalog, IEmbeddingClient embeddings, string modelo, IEmbeddingCache? cache = null, int topK = DefaultTopK)
    {
        ArgumentNullException.ThrowIfNull(catalog);
        ArgumentNullException.ThrowIfNull(embeddings);
        ArgumentOutOfRangeException.ThrowIfLessThan(topK, 1);
        _catalog = catalog;
        _embeddings = embeddings;
        _modelo = modelo ?? "";
        _cache = cache;
        _topK = topK;
    }

    public async Task<IReadOnlyList<Fragmento>> RecuperarAsync(string pregunta, CancellationToken ct)
    {
        var rank = await RankearAsync(pregunta, ct).ConfigureAwait(false);
        return rank.Take(_topK).Select(RetrievalFilter.ToFragmento).ToList();
    }

    public async Task<IReadOnlyList<Chunk>> RankearAsync(string pregunta, CancellationToken ct)
    {
        var elegibles = RetrievalFilter.Elegibles(_catalog.Chunks, pregunta).ToList();
        if (elegibles.Count == 0 || string.IsNullOrWhiteSpace(pregunta))
        {
            return [];
        }

        var vectores = await VectoresDeChunksAsync(ct).ConfigureAwait(false);
        var q = (await _embeddings.VectorizarAsync([pregunta], ct).ConfigureAwait(false)).Single();
        return elegibles
            .Select((c, i) => (Chunk: c, Indice: i, Score: Vectores.Coseno(q, vectores[c.ChunkId])))
            .OrderByDescending(x => x.Score)
            .ThenBy(x => x.Indice)
            .Select(x => x.Chunk)
            .ToList();
    }

    private static string TextoIndexable(Chunk c) => c.Titulo + "\n" + c.Texto;

    private async Task<Dictionary<string, float[]>> VectoresDeChunksAsync(CancellationToken ct)
    {
        if (_vectores is not null)
        {
            return _vectores;
        }

        await _init.WaitAsync(ct).ConfigureAwait(false);
        try
        {
            if (_vectores is not null)
            {
                return _vectores;
            }

            // Solo chunks confiables (vigentes o no): el contenido en cuarentena no sale hacia el proveedor.
            var confiables = _catalog.Chunks.Where(c => !c.Untrusted).ToList();
            var resultado = new Dictionary<string, float[]>(StringComparer.Ordinal);
            var pendientes = new List<Chunk>();
            foreach (var c in confiables)
            {
                var v = _cache?.Obtener(Clave(c));
                if (v is not null)
                {
                    resultado[c.ChunkId] = v;
                }
                else
                {
                    pendientes.Add(c);
                }
            }

            for (var i = 0; i < pendientes.Count; i += Lote)
            {
                var lote = pendientes.Skip(i).Take(Lote).ToList();
                var vs = await _embeddings.VectorizarAsync(lote.Select(TextoIndexable).ToList(), ct).ConfigureAwait(false);
                if (vs.Count != lote.Count)
                {
                    throw new InvalidOperationException("El proveedor de embeddings devolvio una cantidad distinta de vectores.");
                }

                for (var j = 0; j < lote.Count; j++)
                {
                    resultado[lote[j].ChunkId] = vs[j];
                    _cache?.Guardar(Clave(lote[j]), vs[j]);
                }
            }

            if (pendientes.Count > 0)
            {
                _cache?.Persistir();
            }

            _vectores = resultado;
            return resultado;
        }
        finally
        {
            _init.Release();
        }
    }

    private string Clave(Chunk c) => _modelo + "|" + c.Hash;
}

/// <summary>Reciprocal Rank Fusion: score = suma 1/(k + rango), rango desde 1.</summary>
public static class Rrf
{
    public const int DefaultK = 60;

    public static IReadOnlyList<string> Fusionar(IReadOnlyList<IReadOnlyList<string>> rankings, int k = DefaultK)
    {
        var score = new Dictionary<string, double>(StringComparer.Ordinal);
